def finding(item, ordinal, refs):
    fid, name, primary = item
    low = name.lower()
    kinds = [primary, KINDS[(ordinal + 9) % len(KINDS)], KINDS[(ordinal + 18) % len(KINDS)]]
    return {"id": fid, "name": name,
            "description": f"Records {low} as source-qualified Security Holding context while instrument, issuance, party, account, register, custody, trade, settlement, payment, ledger, tax lot, valuation, corporate action, tax, filing and records masters remain external.",
            "source_refs": refs,
            "questions": [
                {"id": f"{fid}-q01", "text": f"Which stable holding, version, holder capacity, security, account or register context and master-system identities establish {low}?", "kind": kinds[0], "answer_data": ["holding and version identifiers, namespace, position key, predecessor and successor", "security, issuance, account, register, custody chain, holder and capacity references", "source status, effective interval, observation time, knowledge time and confidence"]},
                {"id": f"{fid}-q02", "text": f"Who owns, holds, controls, services, reports, validates, changes or may access {low}, under what authority and role?", "kind": kinds[1], "answer_data": ["legal owner, beneficial owner, registered holder, nominee, custodian, account servicer, manager, issuer and authority roles", "agreement, mandate, title evidence, disclosure rule, access purpose, approval and delegated authority", "assertion owner, source, reviewer, steward, contested state and applicable restriction"]},
                {"id": f"{fid}-q03", "text": f"Which quantity, unit, balance bucket, lot, right, restriction, event, evidence, uncertainty and lineage qualify {low}?", "kind": kinds[2], "answer_data": ["quantity, unit, percentage, settled, available, blocked, pledged, lent, borrowed and pending balances", "lot, acquisition, disposal, trade, settlement, corporate action, entitlement, instruction, movement and external outcome references", "source record, digest, reconciliation result, contradiction, event and knowledge times and semantic-loss declaration"]}],
            "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed values and references needed to answer the governed questions for {low} without copying external master lifecycles.", "value_kind": "object", "cardinality": "1", "required": True, "source_refs": refs}],
            "artifacts": [{"id": f"{fid}-artifact", "name": f"{name} evidence manifest", "description": f"Digest-addressed manifest for authoritative balance assertions, rights, events, reconciliations, mappings and external records supporting {low}.", "media_or_form": ["application/json", "application/yaml", "text/markdown", "external reference"], "serial": True, "identity_strategy": "Authoritative master-system identifier first, otherwise governed IRI, then Dimension UUID or ULID; include immutable revision and digest.", "source_refs": refs}],
            "inline_only_rationale": None}


def structure():
    out, ordinal = [], 0
    for bid, bname, rationale, layers in ROWS:
        built_layers, bundle_refs = [], []
        for lid, lname, refs, items in layers:
            bundle_refs.extend(refs)
            built = []
            for item in items:
                ordinal += 1
                built.append(finding(item, ordinal, refs))
            built_layers.append({"id": lid, "name": lname, "description": f"Groups governed findings for {lname.lower()} while preserving the Security Holding boundary and source authority.", "source_refs": refs, "findings": built})
        out.append({"id": bid, "name": bname, "description": rationale, "rationale": rationale, "source_refs": list(dict.fromkeys(bundle_refs)), "layers": built_layers})
    return {"bundles": out}


